CREATE TABLE `edu_resource` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(200) NOT NULL COMMENT '资源标题',
  `description` varchar(500) DEFAULT '' COMMENT '资源简介',
  `cover_url` varchar(500) DEFAULT '' COMMENT '封面图片URL',
  `type` varchar(20) NOT NULL DEFAULT 'document' COMMENT '资源类型: document/code/mindmap',
  `source` varchar(20) DEFAULT 'internal' COMMENT '来源',
  `source_url` varchar(500) DEFAULT '' COMMENT '外部链接',
  `bvid` varchar(30) DEFAULT '' COMMENT '外部ID',
  `duration` varchar(50) DEFAULT '' COMMENT '时长/阅读时间描述',
  `tag` varchar(50) DEFAULT '' COMMENT '标签',
  `icon` varchar(10) DEFAULT 0xF09F9396 COMMENT '卡片图标emoji',
  `header_color` varchar(20) DEFAULT '#ffe4d6' COMMENT '卡片头部背景色',
  `sort_order` int DEFAULT '0' COMMENT '排序权重',
  `content` mediumtext COMMENT '资源正文内容(富文本/代码/markdown)',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID（AI生成资源归属用户）',
  `status` char(1) DEFAULT '0' COMMENT '状态: 0=正常 1=下架',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI生成资源表';
/*!40101 SET character_set_client = @saved_cs_client */;

