INSERT INTO `edu_resource` (`id`, `title`, `description`, `cover_url`, `type`, `source`, `source_url`, `bvid`, `duration`, `tag`, `icon`, `header_color`, `sort_order`, `content`, `user_id`, `status`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (1,'[Python] Python基础','','','code','internal','','','','代码案例','📖','#ffe4d6',0,'### 问题描述\n本案例旨在演示如何编写一个Python程序，接收用户输入的圆的半径，并计算并输出圆的面积与周长。\n\n### 解题思路\n1. **获取用户输入**：使用 `input()` 函数提示用户输入半径。\n2. **处理数据类型**：将用户输入的字符串转换为浮点数 `float`，以便进行数学运算。\n3. **计算面积与周长**：根据数学公式，分别计算圆的面积（πr²）和周长（2πr）。\n4. **格式化输出**：使用格式化字符串（f-string）清晰地展示计算结果，保留合适的小数位数。\n5. **异常处理（进阶）**：考虑到用户可能输入非数字内容，应使用 `try-except` 结构来保证程序的健壮性。\n\n### 完整代码\n```python\n# 导入数学模块，以便使用其中的圆周率常量 pi 和幂运算函数 pow\nimport math\n\ndef calculate_circle(radius):\n    \"\"\"\n    计算并返回圆的面积和周长。\n    \n    参数:\n    radius (float): 圆的半径\n    \n    返回:\n    tuple: 包含面积和周长的元组\n    \"\"\"\n    # 使用 math 模块的 pi 常量，确保精度\n    area = math.pi * pow(radius, 2)  # 面积公式：π * r²\n    circumference = 2 * math.pi * radius  # 周长公式：2 * π * r\n    return area, circumference\n\ndef main():\n    \"\"\"程序主函数\"\"\"\n    print(\"欢迎使用圆计算器！\")\n    \n    # 【易错】：input() 函数返回的永远是字符串，必须进行类型转换\n    try:\n        # 获取用户输入并立即转换为浮点数\n        radius_str = input(\"请输入圆的半径：\")\n        radius = float(radius_str)\n        \n        # 【易错】：在进行数学运算前，应检查半径是否为负数（一个有效的几何输入）\n        if radius < 0:\n            print(\"错误：半径不能为负数。\")\n            return\n        \n        # 调用计算函数，解包返回的元组\n        area, circumference = calculate_circle(radius)\n        \n        # 使用 f-string 进行格式化输出，:.2f 表示保留两位小数\n        # 【易错】：f-string 是 Python 3.6+ 引入的，确保环境兼容；旧版本可使用 .format() 方法\n        print(f\"\\n计算结果：\")\n        print(f\"圆的面积是：{area:.2f}\")\n        print(f\"圆的周长是：{circumference:.2f}\")\n        \n    except ValueError:\n        # 当用户输入无法转换为浮点数时，会触发此异常\n        # 【易错】：捕获到异常后应给出明确提示，而不是让程序崩溃\n        print(\"错误：请输入有效的数字。\")\n\n# 程序入口\nif __name__ == \'__main__\':\n    main()\n\n# 预期输出（假设用户输入半径为 5）：\n# 欢迎使用圆计算器！\n# 请输入圆的半径：5\n# \n# 计算结果：\n# 圆的面积是：78.54\n# 圆的周长是：31.42\n```\n\n### 关键知识点\n1. **输入与输出**：`input()` 函数获取用户输入，`print()` 函数输出结果。\n2. **数据类型与转换**：理解字符串 (`str`) 与浮点数 (`float`) 的区别，使用 `float()` 进行转换。\n3. **模块导入**：使用 `import` 语句导入标准库 `math` 以使用其常量和函数。\n4. **函数定义与调用**：将计算逻辑封装在函数中，实现代码复用和模块化。\n5. **异常处理**：使用 `try-except` 结构来优雅地处理程序运行时可能发生的错误。\n\n### 测试用例\n**测试用例 1（正常输入）**\n- 输入：`10`\n- 预期输出：\n  ```\n  圆的面积是：314.16\n  圆的周长是：62.83\n  ```\n\n**测试用例 2（边界情况：零）**\n- 输入：`0`\n- 预期输出：\n  ```\n  圆的面积是：0.00\n  圆的周长是：0.00\n  ```\n\n**测试用例 3（错误输入：非数字）**\n- 输入：`abc`\n- 预期输出：\n  ```\n  错误：请输入有效的数字。\n  ```\n\n**测试用例 4（错误输入：负数）**\n- 输入：`-5`\n- 预期输出：\n  ```\n  错误：半径不能为负数。\n  ```',1,'0','AI','2026-06-17 10:30:15','','2026-06-17 10:30:15','');
INSERT INTO `edu_resource` (`id`, `title`, `description`, `cover_url`, `type`, `source`, `source_url`, `bvid`, `duration`, `tag`, `icon`, `header_color`, `sort_order`, `content`, `user_id`, `status`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (2,'[Python] 二叉树','','','code','internal','','','','代码案例','📖','#ffe4d6',0,'### 问题描述\n本代码案例将构建一个二叉树数据结构，并通过递归方法计算其深度，同时演示二叉树的先序遍历过程。\n\n### 解题思路\n1. **定义二叉树节点**：使用类来定义二叉树节点，每个节点包含数据域和指向左右子节点的指针域。\n2. **递归计算深度**：采用递归策略，当前树的深度等于其左右子树中较深深度加1。\n3. **遍历验证结构**：实现先序遍历（根-左-右）来验证二叉树构建的正确性。\n4. **主函数驱动**：创建测试二叉树，调用计算深度和遍历函数，并输出结果。\n\n### 完整代码\n```python\nfrom typing import Optional, List\n\nclass TreeNode:\n    \"\"\"二叉树节点类\"\"\"\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val      # 节点存储的数据\n        self.left = left    # 指向左子节点的指针\n        self.right = right  # 指向右子节点的指针\n\ndef max_depth(root: Optional[TreeNode]) -> int:\n    \"\"\"\n    计算二叉树的最大深度（递归法）\n    \n    Args:\n        root: 二叉树的根节点\n    \n    Returns:\n        int: 树的最大深度，空树深度为0\n    \"\"\"\n    # 【易错】递归基本情况：空节点的深度为0\n    if root is None:\n        return 0\n    \n    # 【易错】递归计算左右子树深度，注意是分开调用，不能直接用+连接\n    left_depth = max_depth(root.left)\n    right_depth = max_depth(root.right)\n    \n    # 当前树的深度 = 左右子树较深深度 + 1（当前根节点）\n    return max(left_depth, right_depth) + 1\n\ndef preorder_traversal(root: Optional[TreeNode]) -> List[int]:\n    \"\"\"\n    二叉树的先序遍历（递归法）\n    \n    Args:\n        root: 二叉树的根节点\n    \n    Returns:\n        List[int]: 先序遍历结果列表\n    \"\"\"\n    result = []\n    \n    # 【易错】递归基本情况：空节点直接返回，不添加值\n    if root is None:\n        return result\n    \n    # 【易错】先序遍历顺序：根 -> 左 -> 右，顺序不能错\n    result.append(root.val)               # 先访问根节点\n    result.extend(preorder_traversal(root.left))  # 递归遍历左子树\n    result.extend(preorder_traversal(root.right)) # 递归遍历右子树\n    \n    return result\n\ndef main():\n    \"\"\"主函数：构建测试二叉树并执行相关操作\"\"\"\n    \n    # 手动构建一个二叉树用于测试\n    #       1\n    #      / \\\n    #     2   3\n    #    / \\\n    #   4   5\n    root = TreeNode(1)                      # 根节点\n    root.left = TreeNode(2)                 # 根的左子节点\n    root.right = TreeNode(3)                # 根的右子节点\n    root.left.left = TreeNode(4)            # 节点2的左子节点\n    root.left.right = TreeNode(5)           # 节点2的右子节点\n    \n    # 1. 计算二叉树深度\n    depth = max_depth(root)\n    print(f\"二叉树的最大深度: {depth}\")\n    \n    # 2. 先序遍历二叉树\n    preorder_result = preorder_traversal(root)\n    print(f\"先序遍历结果: {preorder_result}\")\n    \n    # 3. 测试空树情况\n    empty_tree_depth = max_depth(None)\n    print(f\"空树的深度: {empty_tree_depth}\")\n    \n    # 4. 测试单节点树\n    single_node = TreeNode(100)\n    single_node_depth = max_depth(single_node)\n    print(f\"单节点树的深度: {single_node_depth}\")\n\nif __name__ == \'__main__\':\n    main()\n\n# 预期输出:\n# 二叉树的最大深度: 3\n# 先序遍历结果: [1, 2, 4, 5, 3]\n# 空树的深度: 0\n# 单节点树的深度: 1\n```\n\n### 关键知识点\n1. **二叉树节点定义**：理解节点结构（数据域+指针域）是学习树结构的基础。\n2. **递归思想**：深度计算和遍历都体现了“分而治之”的递归思想，理解递归基本情况和递推关系是关键。\n3. **三种基本遍历**：先序（根-左-右）、中序（左-根-右）、后序（左-右-根）遍历是树操作的核心。\n4. **类型提示使用**：使用 `Optional` 和类型提示增强代码可读性和健壮性。\n5. **边界条件处理**：空树（`None`）和单节点树是测试算法正确性的重要边界情况。\n\n### 测试用例\n**测试用例 1**：\n```python\n# 输入：空树 (None)\n# 预期输出：\n#   深度: 0\n#   遍历结果: []\n```\n\n**测试用例 2**：\n```python\n# 输入：只有根节点的树 (节点值=5)\n# 预期输出：\n#   深度: 1\n#   先序遍历结果: [5]\n```\n\n**测试用例 3**：\n```python\n# 输入：完全二叉树\n#       1\n#      / \\\n#     2   3\n#    / \\ / \\\n#   4  5 6  7\n# 预期输出：\n#   深度: 3\n#   先序遍历结果: [1, 2, 4, 5, 3, 6, 7]\n```',1,'0','AI','2026-06-17 10:37:47','','2026-06-17 10:37:47','');
INSERT INTO `edu_resource` (`id`, `title`, `description`, `cover_url`, `type`, `source`, `source_url`, `bvid`, `duration`, `tag`, `icon`, `header_color`, `sort_order`, `content`, `user_id`, `status`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (3,'机器学习基础框架','','','mindmap','internal','','','','png_base64','📖','#ffe4d6',0,'data:image/png;base64,',1,'0','AI','2026-06-17 10:40:53','','2026-06-17 10:40:53','');
INSERT INTO `edu_resource` (`id`, `title`, `description`, `cover_url`, `type`, `source`, `source_url`, `bvid`, `duration`, `tag`, `icon`, `header_color`, `sort_order`, `content`, `user_id`, `status`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (4,'[Python] 冒泡排序','','','code','internal','','','','代码案例','📖','#ffe4d6',0,'# 冒泡排序 Python 教学代码案例\n\n### 问题描述\n本代码案例旨在解决一个基础的排序问题：给定一个包含若干个数字的列表，通过**冒泡排序**算法将其按从小到大的顺序重新排列。\n\n### 解题思路\n1.  **理解核心机制**：冒泡排序重复地遍历待排序的列表，每次比较相邻的两个元素，如果它们的顺序错误（即前面的元素比后面的大），就交换它们的位置。\n2.  **设计外层循环**：使用外层循环控制排序的“轮数”。每完成一轮，未排序部分中最大的元素就会像“气泡”一样被交换到它应在的最终位置。\n3.  **设计内层循环**：使用内层循环进行每一轮的“比较与交换”。每轮比较的次数可以递减，因为上一轮确定的最大元素已无需再参与比较。\n4.  **实现交换**：通过一个临时变量，交换两个相邻元素在列表中的位置。\n5.  **优化可能**：如果在某一轮内层循环中没有发生任何交换，说明列表已经有序，可以提前结束排序。\n\n### 完整代码\n```python\ndef bubble_sort(unsorted_list):\n    \"\"\"\n    使用冒泡排序算法对列表进行就地排序（升序）。\n    Args:\n        unsorted_list: 待排序的列表（包含可比较的元素，如数字）。\n    Returns:\n        None. 该函数直接修改传入的列表。\n    \"\"\"\n    n = len(unsorted_list)  # 获取列表长度，用于确定循环范围\n    # 【易错】外层循环控制排序轮数。n个元素最多需要 n-1 轮排序，而不是 n 轮。\n    # 例如，对5个数排序，最多比较4轮（第5个元素的位置自然确定）。\n    for i in range(n - 1):\n        # 【易错】设置一个标志位，用于本轮是否发生了交换。\n        # 如果为False，说明本轮未发生交换，列表已有序，可提前终止。\n        sorted_flag = True\n\n        # 内层循环进行每一轮的相邻元素比较与交换。\n        # 【易错】内层循环的范围是 `range(n - 1 - i)`，而不是 `range(n-1)`。\n        # 每完成一轮，末尾就多确定一个最大元素，因此比较的边界要向前收缩。\n        for j in range(0, n - 1 - i):\n            # 比较相邻的两个元素，如果前一个比后一个大，则顺序错误，需要交换。\n            if unsorted_list[j] > unsorted_list[j + 1]:\n                # 【易错】交换两个变量的值必须使用临时变量（或Python的元组交换）。\n                # 常见错误是直接 `a[j] = a[j+1]; a[j+1] = a[j]`，这会导致值丢失。\n                unsorted_list[j], unsorted_list[j + 1] = unsorted_list[j + 1], unsorted_list[j]\n                sorted_flag = False  # 发生了交换，标记本轮不是有序的\n\n        # 优化：如果本轮没有发生任何交换，说明列表已经完全有序，无需继续后续轮次。\n        if sorted_flag:\n            break\n\nif __name__ == \'__main__\':\n    # 创建一个测试用例\n    data = [64, 34, 25, 12, 22, 11, 90]\n    print(\"排序前的列表:\", data)\n\n    # 调用排序函数\n    bubble_sort(data)\n\n    # 函数直接修改了列表，因此输出修改后的列表\n    print(\"排序后的列表:\", data)\n\n# 预期输出:\n# 排序前的列表: [64, 34, 25, 12, 22, 11, 90]\n# 排序后的列表: [11, 12, 22, 25, 34, 64, 90]\n```\n\n### 关键知识点\n1.  **双重循环结构**：外层循环控制排序进程，内层循环执行核心的比较和交换操作。\n2.  **相邻元素比较**：这是冒泡排序最基础的操作，每次只比较索引 `j` 和 `j+1` 的元素。\n3.  **交换操作**：理解通过临时变量（或Python的元组赋值）交换两个变量值的原理。\n4.  **算法优化（提前终止）**：通过一个标志位（`sorted_flag`）判断排序是否可以提前结束，提升最好情况（列表基本有序）下的效率。\n5.  **时间复杂度**：理解冒泡排序的平均和最坏时间复杂度为 O(n²)，最好时间复杂度（优化后）为 O(n)。\n\n### 测试用例\n1.  **输入**: `[5, 3, 8, 4, 2]`\n    **预期输出**: `[2, 3, 4, 5, 8]`\n    *(说明：测试基本的乱序列表)*\n\n2.  **输入**: `[10, 9, 8, 7, 6]`\n    **预期输出**: `[6, 7, 8, 9, 10]`\n    *(说明：测试完全逆序的列表，这是冒泡排序最坏情况)*\n\n3.  **输入**: `[1, 2, 4, 3, 5]`\n    **预期输出**: `[1, 2, 3, 4, 5]`\n    *(说明：测试接近有序的列表，旨在验证“提前终止”优化是否生效。内层循环仅在第一轮发生一次交换，第二轮即触发`sorted_flag`为True而终止。)*',1,'0','AI','2026-06-17 11:08:55','','2026-06-17 11:08:55','');
